CREATE TABLE customers(id VARCHAR(128) PRIMARY KEY,display_name VARCHAR(255) NOT NULL,status VARCHAR(16) NOT NULL CHECK(status IN ('ACTIVE','CLOSED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts(id VARCHAR(128) PRIMARY KEY,customer_id VARCHAR(128) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency CHAR(3) NOT NULL CHECK(currency='JOD'),available_balance NUMERIC(19,3) NOT NULL CHECK(available_balance>=0),opening_balance NUMERIC(19,3) NOT NULL CHECK(opening_balance>=0),status VARCHAR(16) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')),allow_incoming BOOLEAN NOT NULL DEFAULT true,transfer_limit NUMERIC(19,3) NOT NULL DEFAULT 10000 CHECK(transfer_limit>0),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE account_debit_grants(account_id VARCHAR(128) REFERENCES accounts(id) ON DELETE RESTRICT,principal VARCHAR(128) NOT NULL,PRIMARY KEY(account_id,principal));
-- Business-rejected instructions can name absent accounts, so payment account references deliberately have no FK.
CREATE TABLE payments(payment_id UUID PRIMARY KEY,from_account_id VARCHAR(128) NOT NULL,to_account_id VARCHAR(128) NOT NULL,amount NUMERIC(19,3) NOT NULL CHECK(amount>0),currency CHAR(3) NOT NULL CHECK(currency='JOD'),instruction_date TIMESTAMPTZ NOT NULL,purpose VARCHAR(255) NOT NULL,notes VARCHAR(1000),payload_fingerprint CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL CHECK(status IN ('COMPLETED','REJECTED')),rejection_code VARCHAR(64),http_status INTEGER NOT NULL DEFAULT 409,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ NOT NULL DEFAULT now(),requested_by VARCHAR(128) NOT NULL,correlation_id VARCHAR(64) NOT NULL);
CREATE INDEX payments_source_time ON payments(from_account_id,created_at);
CREATE INDEX payments_destination_time ON payments(to_account_id,created_at);
CREATE INDEX payments_created ON payments(created_at);
CREATE TABLE ledger_entries(id BIGSERIAL PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id VARCHAR(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type VARCHAR(8) NOT NULL CHECK(entry_type IN ('DEBIT','CREDIT')),signed_amount NUMERIC(19,3) NOT NULL,balance_after NUMERIC(19,3) NOT NULL CHECK(balance_after>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id,id);
CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial history is immutable'; END $$;
CREATE TRIGGER ledger_no_mutation BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE FUNCTION immutable_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.rejection_code IS DISTINCT FROM 'REGISTERING' THEN RAISE EXCEPTION 'Payment history is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_no_mutation BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_payment();
CREATE FUNCTION check_payment_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p UUID; state VARCHAR; n BIGINT; total NUMERIC; BEGIN p:=NEW.payment_id; SELECT status INTO state FROM payments WHERE payment_id=p; SELECT count(*),coalesce(sum(signed_amount),0) INTO n,total FROM ledger_entries WHERE payment_id=p; IF state='COMPLETED' AND (n<>2 OR total<>0) THEN RAISE EXCEPTION 'Unbalanced completed payment'; END IF; IF state='REJECTED' AND n<>0 THEN RAISE EXCEPTION 'Rejected payment has ledger'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER payment_balanced AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_payment_ledger();
CREATE CONSTRAINT TRIGGER ledger_balanced AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_payment_ledger();
CREATE TABLE request_limits(principal VARCHAR(255) PRIMARY KEY,window_start TIMESTAMPTZ NOT NULL,requests BIGINT NOT NULL CHECK(requests>0));
